using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using Sdt.Core;
using Sdt.Core.Battle;
sealed class Host:BattleHost {
 public int Hp{get;set;}=30;public int MaxHp=>60;public int Atk=>4;public int SpellPower=>0;public string MyClass=>null;public string CharacterId=>"wu";
 public IReadOnlyList<OwnedCard> OwnedCards=>Array.Empty<OwnedCard>();public void Log(string s,string k=null){}public void Heal(int n)=>Hp=Math.Min(MaxHp,Hp+n);public void OnBattleEnd(BattleResult r){}
}
class Audit {
 static readonly string Dir="_planning/migration-1029/current-node-rooms/isolated/current-forecast/";
 static readonly BindingFlags BF=BindingFlags.NonPublic|BindingFlags.Instance;
 static readonly List<object> Rows=new List<object>();static int fails;
 static object Get(BattleSession b,string n)=>typeof(BattleSession).GetField(n,BF).GetValue(b);
 static void Set(BattleSession b,string n,object v)=>typeof(BattleSession).GetField(n,BF).SetValue(b,v);
 static object Call(BattleSession b,string n,params object[] args)=>typeof(BattleSession).GetMethod(n,BF).Invoke(b,args);
 static JsonElement At(JsonElement e,string key)=>e.ValueKind==JsonValueKind.Object&&e.TryGetProperty(key,out var v)?v:default;
 static int Num(JsonElement e,string key,int d=0)=>At(e,key).ValueKind==JsonValueKind.Number?At(e,key).GetInt32():d;
 static bool Flag(JsonElement e,string key)=>At(e,key).ValueKind==JsonValueKind.True;
 static string Str(JsonElement e,string key)=>At(e,key).ValueKind==JsonValueKind.String?At(e,key).GetString():null;
 static Dictionary<string,int> Status(JsonElement e)=>e.ValueKind==JsonValueKind.Object?e.EnumerateObject().ToDictionary(p=>p.Name,p=>p.Value.GetInt32()):new Dictionary<string,int>();
 static DefenseState Defense(JsonElement e)=>new DefenseState{Armor=Num(e,"armor"),Shield=Num(e,"shield"),Guard=Flag(e,"guard")};
 static FoeSnapshot Foe(JsonElement e){var f=new FoeSnapshot{name=Str(e,"name"),hp=Num(e,"hp"),maxHp=Num(e,"maxHp"),atk=Num(e,"atk"),affix=Str(e,"affix"),behavior=Str(e,"behavior"),dead=Flag(e,"dead"),evenAttack=Flag(e,"evenAttack"),Statless=Flag(e,"statless"),status=Status(At(e,"status")),defense=Defense(At(e,"defense"))};
  foreach(var key in new[]{"stunned","noFirstAttack"})typeof(FoeSnapshot).GetField(key)?.SetValue(f,Flag(e,key));return f;}
 static BattleSnapshot Snap(JsonElement e)=>new BattleSnapshot{turn=Num(e,"turn",1),player=new PlayerSnapshot{hp=Num(At(e,"player"),"hp")},pstat=new PstatSnapshot{status=Status(At(At(e,"pstat"),"status"))},pdef=Defense(At(e,"pdef")),Allies=At(e,"allies").EnumerateArray().Select(Foe).ToArray(),foes=At(e,"foes").EnumerateArray().Select(Foe).ToArray(),EndTurnContext=new EndTurnContextSnapshot{DeathSave=Num(At(e,"endTurnContext"),"deathSave"),ExtraTurn=Flag(At(e,"endTurnContext"),"extraTurn"),TimeRune=Flag(At(e,"endTurnContext"),"timeRune")}};
 static bool Same(JsonElement a,JsonElement b){if(a.ValueKind!=b.ValueKind)return false;if(a.ValueKind==JsonValueKind.Object){var aa=a.EnumerateObject().OrderBy(p=>p.Name).ToArray();var bb=b.EnumerateObject().OrderBy(p=>p.Name).ToArray();return aa.Length==bb.Length&&aa.Zip(bb,(x,y)=>x.Name==y.Name&&Same(x.Value,y.Value)).All(x=>x);}if(a.ValueKind==JsonValueKind.Array){var aa=a.EnumerateArray().ToArray();var bb=b.EnumerateArray().ToArray();return aa.Length==bb.Length&&aa.Zip(bb,Same).All(x=>x);}return a.GetRawText()==b.GetRawText();}
 static void Check(string name,object actual,object expected){using var a=JsonDocument.Parse(JsonSerializer.Serialize(actual));using var e=JsonDocument.Parse(JsonSerializer.Serialize(expected));bool equal=Same(a.RootElement,e.RootElement);Rows.Add(new{name,actual,expected,equal});if(!equal)fails++;}
 static void Apply(Combatant u,JsonElement e){u.name=Str(e,"name");u.hp=Num(e,"hp");u.maxHp=Num(e,"maxHp");u.atk=Num(e,"atk");u.dead=Flag(e,"dead");u.defense=Defense(At(e,"defense"));foreach(var p in Status(At(e,"status")))u.status.Set(p.Key,p.Value);}
 static (BattleSession b,Host h) Start(JsonElement e){var h=new Host{Hp=Num(At(e,"player"),"hp")};var b=new BattleSession();b.Start(new BattleStartContext{host=h,rng=new Rng(123),enemies=new[]{new EnemyInput{id="target",name="靶子",hp=100,atk=8}}});
  Set(b,"turn",Math.Max(1,Num(e,"turn",1)));Set(b,"pdef",Defense(At(e,"pdef")));var ps=(Combatant)Get(b,"pstat");foreach(var p in Status(At(At(e,"pstat"),"status")))ps.status.Set(p.Key,p.Value);Set(b,"deathSaves",Num(At(e,"endTurnContext"),"deathSave"));Set(b,"extraTurn",Flag(At(e,"endTurnContext"),"extraTurn"));
  var fs=new List<BattleFoe>();foreach(var fe in At(e,"foes").EnumerateArray()){var f=new BattleFoe();Apply(f,fe);f.affix=Str(fe,"affix");f.behavior=Str(fe,"behavior");f.evenAttack=Flag(fe,"evenAttack");foreach(var key in new[]{"stunned","noFirstAttack"})typeof(BattleFoe).GetField(key)?.SetValue(f,Flag(fe,key));fs.Add(f);}Set(b,"foes",fs);
  var allies=(IList)Get(b,"ruleAllies");foreach(var ae in At(e,"allies").EnumerateArray()){var a=(Combatant)Activator.CreateInstance(allies.GetType().GetGenericArguments()[0],true);Apply(a,ae);a.GetType().GetField("statless").SetValue(a,Flag(ae,"statless"));allies.Add(a);}return(b,h);
 }
 static object ForecastValue(BattleTurnForecastResult f)=>new{damage=f.Damage,hpAfter=f.HpAfter,lethal=f.Lethal,note=f.Note};
 static void Main(string[] args){CardLibrary.Init(()=>CardDatabase.All);using var doc=JsonDocument.Parse(System.IO.File.ReadAllText(Dir+"source-vectors.json"));var root=doc.RootElement;
  foreach(var row in root.GetProperty("forecast").EnumerateArray()){var s=Snap(row.GetProperty("input"));var before=JsonSerializer.Serialize(s,new JsonSerializerOptions{IncludeFields=true});Check("forecast:"+Str(row,"name"),ForecastValue(BattleTurnForecast.Estimate(s)),row.GetProperty("expected"));Check("forecast-unmodified:"+Str(row,"name"),JsonSerializer.Serialize(s,new JsonSerializerOptions{IncludeFields=true}),before);}
  var planType=typeof(BattleSession).Assembly.GetType("Sdt.Core.Battle.BattleEnemyPlan");if(planType!=null)foreach(var row in root.GetProperty("plans").EnumerateArray()){var m=planType.GetMethods().Single(m=>m.Name=="Build"&&m.GetParameters()[0].ParameterType==typeof(FoeSnapshot));var plan=m.Invoke(null,new object[]{Foe(row.GetProperty("input")),Num(row,"turn")});var t=plan.GetType();Check("plan:"+Rows.Count,new{kind=(string)t.GetField("Kind").GetValue(plan),skip=(string)t.GetField("Skip").GetValue(plan),canAttack=(bool)t.GetProperty("CanAttack").GetValue(plan),hits=(int)t.GetField("Hits").GetValue(plan)},row.GetProperty("expected"));}
  foreach(var row in root.GetProperty("actual").EnumerateArray()){var(b,h)=Start(row.GetProperty("input"));b.EndTurn();var ps=(Combatant)Get(b,"pstat");var allies=((IList)Get(b,"ruleAllies")).Cast<Combatant>().Select(a=>new{hp=a.hp,dead=a.dead}).ToArray();var fs=(List<BattleFoe>)Get(b,"foes");Check("actual:"+Str(row,"name"),new{hp=h.Hp,deathSave=(int)Get(b,"deathSaves"),poison=ps.status.poison,allies,stunned=fs.Select(f=>(bool?)(typeof(BattleFoe).GetField("stunned")?.GetValue(f))??false).ToArray(),over=b.Snapshot.over,turn=b.Snapshot.turn},row.GetProperty("expected"));}
  int hi=0;foreach(var row in root.GetProperty("hits").EnumerateArray()){var(b,h)=Start(row.GetProperty("input"));int dealt=(int)Call(b,"PlayerTakeHit",new BattleFoe{name="击",atk=Num(row,"atk")});var p=(Combatant)Get(b,"pstat");var d=(DefenseState)Get(b,"pdef");Check("hit:"+hi++,new{dealt,hp=h.Hp,deathSave=(int)Get(b,"deathSaves"),immune=p.status.immune,dodge=p.status.dodge,defense=new{armor=d.Armor,shield=d.Shield,guard=d.Guard}},row.GetProperty("expected"));}
  var pile=root.GetProperty("pile");var seed=root.GetProperty("forecast")[0].GetProperty("input");var(bp,hp)=Start(seed);foreach(var p in pile.GetProperty("input").EnumerateObject())Set(bp,p.Name,p.Value.EnumerateArray().Select(x=>x.GetString()).ToList());Set(bp,"resolvingItemUid","excluded");Check("consumed-pile-union",bp.Snapshot.ConsumedPile,pile.GetProperty("expected"));
  int ii=0;foreach(var row in root.GetProperty("intents").EnumerateArray()){var(b,h)=Start(seed);((Combatant)Get(b,"pstat")).status.bleed=Num(row,"bleed");var e=row.GetProperty("input");var f=new BattleFoe();Apply(f,e);f.behavior=Str(e,"behavior");f.affix=Str(e,"affix");f.evenAttack=Flag(e,"evenAttack");f.noFirstAttack=Flag(e,"noFirstAttack");f.stunned=Flag(e,"stunned");var intent=(FoeIntent)Call(b,"IntentFor",f,Num(row,"turn"));var value=new Dictionary<string,object>{{"kind",intent.kind},{"icon",intent.icon},{"label",intent.label},{"damage",intent.HasDamage?(object)intent.damage:null},{"hits",intent.hits}};if(intent.HasDamage)value["bleedBonus"]=intent.bleedBonus;Check("intent:"+ii++,value,row.GetProperty("expected"));}
  var initial=bp.Snapshot;var token=initial.BattleToken;Check("phase-player",initial.Phase,"player");Check("token-present",!string.IsNullOrEmpty(token),true);var phases=new List<string>();Action<BattleSnapshot> listener=s=>phases.Add(s.Phase);BattleSession.SnapshotChanged+=listener;bp.EndTurn();BattleSession.SnapshotChanged-=listener;Check("phase-enemy-observed",phases.Contains("enemy"),true);Check("phase-next-player",bp.Snapshot.Phase,"player");Check("token-stable-in-battle",bp.Snapshot.BattleToken,token);bp.Retract();Check("phase-retract",bp.Snapshot.Phase,Str(root.GetProperty("phases"),"retract"));Check("retract-over",bp.Snapshot.over,true);
  var(b2,h2)=Start(seed);Check("token-new-battle",b2.Snapshot.BattleToken!=token,true);var sx=b2.Snapshot;var orig=((List<BattleFoe>)Get(b2,"foes"))[0];sx.foes[0].defense.Shield=99;Check("foe-defense-detached",orig.defense.Shield,0);
  var type=typeof(BattleSession).GetNestedType("RuleAlly",BindingFlags.NonPublic);var ar=(Combatant)Activator.CreateInstance(type,true);ar.hp=10;ar.defense.Shield=4;((IList)Get(b2,"ruleAllies")).Add(ar);sx=b2.Snapshot;sx.Allies[0].defense.Shield=99;Check("ally-defense-detached",ar.defense.Shield,4);
  foreach(var row in root.GetProperty("selfDamage").EnumerateArray()){var(b,h)=Start(seed);h.Hp=Num(row,"hp");Set(b,"deathSaves",Num(row,"saves"));var card=new CardDef{id="self",name="自伤",type="法术",cost=0,rules=RuleValue.Obj("version",1,"battle",RuleValue.Obj("target",RuleValue.Obj("side","self","area",false)),"triggers",RuleValue.Obj("onPlay",RuleValue.Arr(RuleValue.Obj("op","heal","selfDamage",Num(row,"n")))))};((List<OwnedCard>)Get(b,"granted")).Add(new OwnedCard{uid="self",card=card});((List<string>)Get(b,"hand")).Add("self");b.PlayCard("self",-1,false);Check("self-damage:"+Num(row,"saves")+":"+Num(row,"n"),new{hp=h.Hp,deathSave=(int)Get(b,"deathSaves"),immune=((Combatant)Get(b,"pstat")).status.immune,over=b.Snapshot.over},row.GetProperty("expected"));}
  var(br,hr)=Start(seed);Call(br,"RegisterRuleName",new CardDef(),RuleValue.Obj("rule","deathSave","n",3));Call(br,"RegisterRuleName",new CardDef(),RuleValue.Obj("rule","deathSave","n",2));Check("insurance-replaces-counter",(int)Get(br,"deathSaves"),Num(root,"repeatedInsurance"));
  var expectedPhases=root.GetProperty("phases");foreach(var win in new[]{true,false}){var(b,h)=Start(seed);Call(b,"Finish",(bool?)win);Check("phase-terminal:"+win,b.Snapshot.Phase,Str(expectedPhases,win?"victory":"defeat"));}
  var(bt,ht)=Start(seed);var targetCard=CardLibrary.FindById("starter-attack").Clone();targetCard.runtimeCost=0;((List<OwnedCard>)Get(bt,"granted")).Add(new OwnedCard{uid="phase-target",card=targetCard});((List<string>)Get(bt,"hand")).Add("phase-target");bt.PlayCard("phase-target",-2,false);Check("phase-targeting",bt.Snapshot.Phase,Str(expectedPhases,"targeting"));bt.CancelPendingTarget();Check("phase-cancel-target",bt.Snapshot.Phase,Str(expectedPhases,"cancelTarget"));var castPhases=new List<string>();Action<BattleSnapshot> castListener=s=>castPhases.Add(s.Phase);BattleSession.SnapshotChanged+=castListener;bt.PlayCard("phase-target",0,false);BattleSession.SnapshotChanged-=castListener;Check("phase-resolving-observed",castPhases.Contains(Str(expectedPhases,"resolving")),true);Check("phase-after-resolve",bt.Snapshot.Phase,Str(expectedPhases,"afterResolve"));
  var bd=new BattleSession();bd.Start(new BattleStartContext{host=new Host(),isBoss=true,enemies=new[]{new EnemyInput{id="boss",name="首脑",hp=30,atk=1}}});Check("phase-deck",bd.Snapshot.Phase,Str(expectedPhases,"deck"));Check("phase-deck-rejects-end",bd.EndTurn().Ok,false);bd.CancelDeckSelection();Check("phase-cancel-deck",bd.Snapshot.Phase,Str(expectedPhases,"cancelDeck"));
  var noFirstHost=new Host();var noFirst=new BattleSession();noFirst.Start(new BattleStartContext{host=noFirstHost,enemies=new[]{new EnemyInput{id="first",name="首回合蓄力",hp=100,atk=8,noFirstAttack=true}}});Check("no-first-input-mapping",noFirst.Snapshot.foes[0].noFirstAttack,true);Check("no-first-forecast",noFirst.Snapshot.Forecast.Damage,0);noFirst.EndTurn();Check("no-first-actual-hp",noFirstHost.Hp,30);
  var checkpoint=noFirst.CaptureCheckpoint();Check("no-first-entry-checkpoint",checkpoint.enemyDefs[0].noFirstAttack,true);var restored=new BattleSession();var restoredHost=new Host();Check("no-first-restore",restored.RestoreCheckpoint(restoredHost,checkpoint,new Rng(123),out var restoreReason),true);Check("no-first-restored-input",restored.Snapshot.foes[0].noFirstAttack,true);restored.EndTurn();Check("no-first-restored-actual-hp",restoredHost.Hp,30);
  var json=JsonSerializer.Serialize(Rows,new JsonSerializerOptions{WriteIndented=true});System.IO.File.WriteAllText(Dir+(args.Length>0?args[0]:"unity-results.json"),json+Environment.NewLine);Console.WriteLine($"Forecast and adjacent source checks: {Rows.Count-fails}/{Rows.Count}; failures: {fails}");foreach(var row in Rows){var j=JsonSerializer.Serialize(row);if(j.Contains("\"equal\":false"))Console.WriteLine(j);}Environment.ExitCode=fails==0?0:1;
 }
}
